package com.jobassistant.dto;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;

/**
 * DTO for authentication request.
 * Sent by the client to /api/v1/auth/login or /api/v1/auth/register.
 * NOTE: email must be unique (enforced by DB and registration logic).
 */
public class AuthRequest {

    @NotBlank(message = "Email is required")
    @Email(message = "Email should be valid")
    private String email;

    @NotBlank(message = "Password is required")
    private String password;

    // Getters and setters are auto-generated by Lombok (not needed here manually)
    // We use private fields with manual getters for validation simplicity.
    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }
    public String getPassword() { return password; }
    public void setPassword(String password) { this.password = password; }
}